window.AUTH=window.AUTH||{};window.AUTH["17-1201"]={"d":"17-1201","id":"2018/17-1201","n":"Thacker v. Tennessee Valley Authority","briefs":[{"k":"petitioner","label":"Brief of petitioners Gary Thacker, et ux","date":"2018-11-13","url":"https://www.supremecourt.gov/DocketPDF/17/17-1201/71802/20181113141017533_17-1201.brief.FINAL.pdf","side":"pet","n":50},{"k":"respondent","label":"Brief of respondent Tennessee Valley Authority","date":"2018-12-13","url":"https://www.supremecourt.gov/DocketPDF/17/17-1201/76181/20181213200913296_17-1201bsUnitedStates.pdf","side":"res","n":89},{"k":"reply","label":"Reply of petitioners Gary Thacker, et ux","date":"2019-01-04","url":"https://www.supremecourt.gov/DocketPDF/17/17-1201/78315/20190104132930009_17-1201.rb.FINAL.pdf","side":"pet","n":31}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1201_j426.pdf","tr":true,"items":[{"t":"case","label":"Am. Nat’l Red Cross v. S.G.","cite":"505 U.S. 247","y":1992,"id":"1991/91-594","sc":1,"sum":"This holding leaves the jurisdiction of the federal courts well within the Article III limits, because the Court has consistently held that Article III's \"arising under\" jurisdiction is broad enough to authorize Congress to confer federal-court jurisdiction over actions involving federally chartered corporations.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Fed. Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Bonner v. City of Prichard","cite":"661 F.2d 1206","y":1981,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/661/1206/","by":{"0":"28"}},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"sum":"The Court ruled that, even though Bowles was relying on the mistaken order of the District Court, the Circuit Court was correct to dismiss his untimely appeal.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"City of Cookeville v. Upper Cumberland Elec. Membership Corp.","cite":"484 F.3d 380","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/484/380/","by":{"0":"12"}},{"t":"case","label":"Conn. v. Am. Elec. Power Co.","cite":"582 F.3d 309","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/582/309/","by":{"0":"22, 23"}},{"t":"case","label":"Edwards v. TVA","cite":"255 F.3d 318","y":2001,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/255/318/","sum":"Holding that discretionary-function exception applies to the TVA.","sumSrc":"brief:0","by":{"0":"22","1":"17"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"op":3,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"18, 19, 40, 41","2":"passim"}},{"t":"case","label":"Fed. Housing Admin. v. Burr","cite":"309 U.S. 242","y":1940,"id":"scdb/1939-089","sc":1,"op":10,"ar":1,"sum":"1. Under the National Housing Act, as amended, which provides that the Administrator shall, in carrying out the provisions of certain of its titles, \"be authorized, in his official capacity, to sue and be sued in any court of competent jurisdiction, State or Federal,\" the Federal Housing Administration is subject to be garnished, under state law, for moneys due to an employee; but only those funds which have been …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"Franchise Tax Bd. of Cal. v. USPS","cite":"467 U.S. 512","y":1984,"id":"1983/83-372","sc":1,"op":1,"sum":"When administrative process of the type employed by appellant issues against appellee, it has been \"sued\" within the meaning of §401(1), and must respond to that process.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 15"}},{"t":"case","label":"Hill v. TVA","cite":"842 F. Supp. 1413","y":1993,"court":"N.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp./842/1413/","by":{"0":"4"}},{"t":"case","label":"Indian Towing Co. v. United States","cite":"350 U.S. 61","y":1955,"id":"1955/8","sc":1,"sum":"If the Coast Guard is negligent in the operation of a lighthouse and damage is caused thereby, the United States is liable under the Tort Claims Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Int’l Primate Protection League v. Adm’rs of Tulane Educ. Fund","cite":"500 U.S. 72","y":1991,"id":"1990/90-89","sc":1,"sum":"Petitioners, organizations and individuals seeking the humane treatment of animals, filed suit in a Louisiana court to enjoin respondents, the Institutes for Behavior Resources (IBR), the National Institutes of Health (NIH), and the Administrators of the Tulane Educational Fund (Tulane), from using certain monkeys for federally funded medical experiments and to obtain custody over the animals. NIH removed the case …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 15, 19"}},{"t":"case","label":"Jackson v. TVA","cite":"462 F. Supp. 45","y":1978,"court":"M.D. Tenn.","url":"https://www.courtlistener.com/c/F.%20Supp./462/45/","by":{"0":"2"}},{"t":"case","label":"J.H. Rutter Rex Mfg. Co. v. United States","cite":"515 F.2d 97","y":1975,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/515/97/","by":{"0":"28"}},{"t":"case","label":"Johns v. Pettibone Corp.","cite":"843 F.2d 464","y":1988,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/843/464/","by":{"0":"5"}},{"t":"case","label":"Loeffler v. Frank","cite":"486 U.S. 549","y":1988,"id":"1987/86-1431","sc":1,"op":3,"sum":"Prejudgment interest may be awarded in a suit against the Postal Service brought under Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"6, 9, 18","2":"passim"}},{"t":"case","label":"Lynn v. United States","cite":"110 F.2d 586","y":1940,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/110/586/","by":{"0":"38"}},{"t":"case","label":"Meyer v. Fidelity Sav.","cite":"944 F.2d 562","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/944/562/","by":{"0":"14"}},{"t":"case","label":"Natural Resources Defense Council, Inc. v. TVA","cite":"459 F.2d 255","y":1972,"court":"2nd Cir.","url":"https://www.courtlistener.com/c/F.2d/459/255/","by":{"0":"9, 19"}},{"t":"case","label":"N.C. ex rel. Cooper v. TVA","cite":"515 F.3d 344","y":2008,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/515/344/","by":{"0":"passim"}},{"t":"case","label":"Neb. ex rel. Dep’t of Soc. Servs. v. Bentson","cite":"146 F.3d 676","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/146/676/","by":{"0":"12"}},{"t":"case","label":"North Carolina ex rel. Cooper v. TVA","cite":"439 F. Supp. 2d 486","y":2006,"court":"W.D.N.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/439/486/","by":{"0":"9, 25"}},{"t":"case","label":"Pac. Nat’l Fire Ins. Co. v. TVA","cite":"89 F. Supp. 978","y":1950,"court":"W.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp./89/978/","by":{"0":"28"}},{"t":"case","label":"Painter v. TVA","cite":"476 F.2d 943","y":1973,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/476/943/","by":{"0":"28"}},{"t":"case","label":"Patchak v. Zinke","cite":"138 S. Ct. 897","y":2018,"id":"2017/16-498","sc":1,"sum":"The Court held that a statute that directs the federal courts to \"promptly dismiss” certain lawsuits without affecting any underlying laws does not violate the Constitution’s separation of powers principles.","sumSrc":"Oyez","by":{"0":"30, 35, 37","2":"10, 11"}},{"t":"case","label":"Peoples Nat’l Bank v. Meredith","cite":"812 F.2d 682","y":1987,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/812/682/","sum":"Finding TVA immune from tort claim arising from agency’s development and administration of a loan program.","sumSrc":"brief:1","by":{"0":"27, 28, 29","1":"9, 16"}},{"t":"case","label":"Pierce v. United States","cite":"314 U.S. 306","y":1941,"id":"scdb/1941-019","sc":1,"sum":"Frauculently impersonating an officer or employee of a corporation owned or controlled by the United States was not an offense under § 32 of the Criminal Code, prior to its amendment by the Act of February 28, 1938. P. 310. 115 F. 2d 399, reversed. CERTIORARI, 313 U. S. 552, to review the affirmance of a conviction under an indictment for violation of § 32 of the Criminal Code. Mr. L. E. Gwinn for petitioner. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 19","1":"32"}},{"t":"case","label":"Queen v. TVA","cite":"689 F.2d 80","y":1982,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/689/80/","sum":"Finding TVA immune from tort claim arising from agency’s actions pursuant to a statutory mandate directing TVA to conduct studies and experiments to promote the wider and better use of electric power.","sumSrc":"brief:1","by":{"0":"27, 28, 29","1":"16"}},{"t":"case","label":"Schillinger v. United States","cite":"155 U.S. 163","y":1894,"id":"scdb/1894-019","sc":1,"sum":"The United States cannot be sued in their courts without their consent.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"30, 35, 37","2":"10"}},{"t":"case","label":"Thacker v. TVA","cite":"188 F. Supp. 3d 1243","y":2015,"court":"N.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/188/1243/","op":1,"by":{"0":"3, 4","2":"7"}},{"t":"case","label":"Thacker v. TVA","cite":"868 F.3d 979","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/868/979/","op":1,"by":{"0":"passim","2":"2, 3, 7"}},{"t":"case","label":"Trainmen v. Toledo, Peoria & W. R.R.","cite":"321 U.S. 50","y":1944,"id":"scdb/1943-097","sc":1,"sum":"1. A railroad company which refused to submit a labor dispute to arbitration in accordance with provisions of the Railway Labor Act-although it had sought to settle the dispute by negotiation and by mediation-has not made \"every reasonable effort\" to settle the dispute, within the meaning of §8 of the Norris-LaGuardia Act, and is thereby barred from injunctive relief in the federal courts.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"United States v. Nordic Village, Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"sum":"After respondent Nordic Village, Inc., filed a petition for relief under Chapter 11 of the Bankruptcy Code, one of its officers withdrew funds from the company's corporate account. He sent part of the money to the Internal Revenue Service (IRS), directing it to apply the funds against his individual tax liability, which it did. In a subsequent adversary proceeding, the Bankruptcy Court permitted Nordic Village's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 12"}},{"t":"case","label":"United States v. Smith","cite":"499 U.S. 160","y":1991,"id":"1990/89-1646","sc":1,"sum":"The Act immunizes Government employees from suit even when an FTCA exception precludes recovery against the Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 27, 29","1":"8, 9, 16"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"13, 14","1":"32"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"0":"1, 35"}},{"t":"usc","label":"12 U.S.C. § 1725","url":"https://www.law.cornell.edu/uscode/text/12/1725","subs":["(c)(4)","(c)(4)(1988)"],"tname":"Banks and Banking","by":{"0":"13","1":"40"}},{"t":"usc","label":"16 U.S.C. § 831c","url":"https://www.law.cornell.edu/uscode/text/16/831c","subs":["(b)","(h)","(i)"],"stext":{"head":"§831c. Corporate powers generally; eminent domain; construction of dams, transmission lines, etc.","paras":[[0,"Except as otherwise specifically provided in this chapter, the Corporation—"],[0,"(a) Shall have succession in its corporate name."],[0,"(b) May sue and be sued in its corporate name."],[0,"(c) May adopt and use a corporate seal, which shall be judicially noticed."],[0,"(d) May make contracts, as herein authorized."],[0,"(e) May adopt, amend, and repeal bylaws."],[0,"(f) May purchase or lease and hold such real and personal property as it deems necessary or convenient in the transaction of its business, and may dispose of any such personal property held by it."],[0,"The Board shall select a treasurer and as many assistant treasurers as it deems proper: Provided, That any member of said Board may be removed from office at any time by a concurrent resolution of the Senate and the House of Representatives."],[0,"(g) Shall have such powers as may be necessary or appropriate for the exercise of the powers herein specifically conferred upon the Corporation."],[0,"(h) Shall have power in the name of the United States of America to exercise the right of eminent domain, and in the purchase of any real estate or the acquisition of real estate by condemnation proceedings, the title to such real estate shall be taken in the name of the United States of America, and thereupon all such real estate shall be entrusted to the Corporation as the agent of the United States to accomplish the purposes of this chapter."],[0,"(i) Shall have power to acquire real estate for the construction of dams, reservoirs, transmission lines, power houses, and other structures, and navigation projects at any point along the Tennessee River, or any of its tributaries, and in the event that the owner or owners of such property shall fail and refuse to sell to the Corporation at a price deemed fair and reasonable by the Board, then the Corporation may proceed to exercise the right of eminent domain, and to condemn all property that it deems necessary for carrying out the purposes of this chapter, and all such condemnation proceedings shall be had pursuant to the provisions and requirements hereinafter specified, with reference to any and all condemnation proceedings: Provided, That nothing contained herein or elsewhere in this chapter shall be construed to deprive the Corporation of the rights conferred by sections 3114, 3115, and 3118 of title 40."],[0,"(j) Shall have power to construct such dams, and reservoirs, in the Tennessee River and its tributaries, as in conjunction with Wilson Dam, and Norris, Wheeler, and Pickwick Landing Dams, now under construction, will provide a nine-foot channel in the said river and maintain a water supply for the same, from Knoxville to its mouth, and will best serve to promote navigation on the Tennessee River and its tributaries and control destructive flood waters in the Tennessee and Mississippi River drainage basins; and shall have power to acquire or construct power houses, power structures, transmission lines, navigation projects, and incidental works in the Tennessee River and its tributaries, and to unite the various power installations into one or more systems by transmission lines."],[0,"(k) Shall have power in the name of the United States—"],[1,"(a) to convey by deed, lease, or otherwise, any real property in the possession of or under the control of the Corporation to any person or persons, for the purpose of recreation or use as a summer residence, or for the operation on such premises of pleasure resorts for boating, fishing, bathing, or any similar purpose;"],[1,"(b) to convey by deed, lease, or otherwise, the possession and control of any such real property to any corporation, partnership, person, or persons for the purpose of erecting thereon docks and buildings for shipping purposes or the manufacture or storage thereon of products for the purpose of trading or shipping in transportation: Provided, That no transfer authorized herein in (b) shall be made without the approval of Congress: And provided further, That said corporation, without further action of Congress, shall have power to convey by deed, lease, or otherwise, to the Ingalls Shipbuilding Corporation, a tract or tracts of land at or near Decatur, Alabama, and to the Commercial Barge Lines, Inc., a tract or tracts of land at or near Guntersville, Alabama;"],[1,"(c) to transfer any part of the possession and control of the real estate now in possession of and under the control of said Corporation to any other department, agency, or instrumentality of the United States: Provided, however, That no land shall be conveyed, leased, or transferred, upon which there is located any permanent dam, hydroelectric power plant, or munitions plant heretofore or hereafter built by or for the United States or for the Authority, except that this prohibition shall not apply to the transfer of Nitrate Plant Numbered 1, at Muscle Shoals, Alabama, or to Waco Quarry: And provided further, That no transfer authorized herein in (a) or (c) except leases for terms of less than twenty years, shall be made without the approval of the President of the United States, if the property to be conveyed exceeds $500 in value; and"],[1,"(d) to convey by warranty deed, or otherwise, lands, easements, and rights-of-way to States, counties, municipalities, school districts, railroad companies, telephone, telegraph, water, and power companies, where any such conveyance is necessary in order to replace any such lands, easements, or rights-of-way to be flooded or destroyed as the result of the construction of any dam or reservoir now under construction by the Corporation, or subsequently authorized by Congress, and easements and rights-of-way upon which are located transmission or distribution lines. The Corporation shall also have power to convey or lease Nitrate Plant Numbered 1, at Muscle Shoals, Alabama, and Waco Quarry, with the approval of the Department of the Army and the President."],[0,"(l) Shall have power to advise and cooperate in the readjustment of the population displaced by the construction of dams, the acquisition of reservoir areas, the protection of watersheds, the acquisition of rights-of-way, and other necessary acquisitions of land, in order to effectuate the purposes of the chapter; and may cooperate with Federal, State, and local agencies to that end."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/16/831c?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§831c. Corporate powers generally; eminent domain; construction of dams, transmission lines, etc.","tname":"Conservation","by":{"0":"1, passim","1":"6, 8, 11, 15, 16, 4, 10, 32, 4, 10, 4, 38","2":"8, 14, 53, 53"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"0":"2"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(b)","(b)(1)"],"stext":{"head":"§1346. United States as defendant","paras":[[0,"(a) The district courts shall have original jurisdiction, concurrent with the United States Court of Federal Claims, of:"],[1,"(1) Any civil action against the United States for the recovery of any internal-revenue tax alleged to have been erroneously or illegally assessed or collected, or any penalty claimed to have been collected without authority or any sum alleged to have been excessive or in any manner wrongfully collected under the internal-revenue laws;"],[1,"(2) Any other civil action or claim against the United States, not exceeding $10,000 in amount, founded either upon the Constitution, or any Act of Congress, or any regulation of an executive department, or upon any express or implied contract with the United States, or for liquidated or unliquidated damages in cases not sounding in tort, except that the district courts shall not have jurisdiction of any civil action or claim against the United States founded upon any express or implied contract with the United States or for liquidated or unliquidated damages in cases not sounding in tort which are subject to sections 7104(b)(1) and 7107(a)(1) of title 41. For the purpose of this paragraph, an express or implied contract with the Army and Air Force Exchange Service, Navy Exchanges, Marine Corps Exchanges, Coast Guard Exchanges, or Exchange Councils of the National Aeronautics and Space Administration shall be considered an express or implied contract with the United States."],[0,"(b)(1) Subject to the provisions of chapter 171 of this title, the district courts, together with the United States District Court for the District of the Canal Zone and the District Court of the Virgin Islands, shall have exclusive jurisdiction of civil actions on claims against the United States, for money damages, accruing on and after January 1, 1945, for injury or loss of property, or personal injury or death caused by the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment, under circumstances where the United States, if a private person, would be liable to the claimant in accordance with the law of the place where the act or omission occurred."],[0,"(2) No person convicted of a felony who is incarcerated while awaiting sentencing or while serving a sentence may bring a civil action against the United States or an agency, officer, or employee of the Government, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(c) The jurisdiction conferred by this section includes jurisdiction of any set-off, counterclaim, or other claim or demand whatever on the part of the United States against any plaintiff commencing an action under this section."],[0,"(d) The district courts shall not have jurisdiction under this section of any civil action or claim for a pension."],[0,"(e) The district courts shall have original jurisdiction of any civil action against the United States provided in section 6226, 6228(a), 7426, or 7428 (in the case of the United States district court for the District of Columbia) or section 7429 of the Internal Revenue Code of 1986."],[0,"(f) The district courts shall have exclusive original jurisdiction of civil actions under section 2409a to quiet title to an estate or interest in real property in which an interest is claimed by the United States."],[0,"(g) Subject to the provisions of chapter 179, the district courts of the United States shall have exclusive jurisdiction over any civil action commenced under section 453(2) of title 3, by a covered employee under chapter 5 of such title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1346?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1346. United States as defendant","tname":"Judiciary and Judicial Procedure","by":{"0":"1, 10, 11, 14, 15, 15","1":"5, 40, 5","2":"12"}},{"t":"usc","label":"28 U.S.C. § 2671","url":"https://www.law.cornell.edu/uscode/text/28/2671","stext":{"head":"§2671. Definitions","paras":[[0,"As used in this chapter and sections 1346(b) and 2401(b) of this title, the term \"Federal agency\" includes the executive departments, the judicial and legislative branches, the military departments, independent establishments of the United States, and corporations primarily acting as instrumentalities or agencies of the United States, but does not include any contractor with the United States."],[0,"\"Employee of the government\" includes (1) officers or employees of any federal agency, members of the military or naval forces of the United States, members of the National Guard while engaged in training or duty under section 115, 316, 502, 503, 504, or 505 of title 32, and persons acting on behalf of a federal agency in an official capacity, temporarily or permanently in the service of the United States, whether with or without compensation, and (2) any officer or employee of a Federal public defender organization, except when such officer or employee performs professional services in the course of providing representation under section 3006A of title 18."],[0,"\"Acting within the scope of his office or employment\", in the case of a member of the military or naval forces of the United States or a member of the National Guard as defined in section 101(3) of title 32, means acting in line of duty."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2671?type=usc&year=mostrecent&link-type=html"},"head":"§2671. Definitions","tname":"Judiciary and Judicial Procedure","by":{"0":"11","1":"33"}},{"t":"usc","label":"28 U.S.C. § 2679","url":"https://www.law.cornell.edu/uscode/text/28/2679","subs":["(a)","(b)(1)"],"stext":{"head":"§2679. Exclusiveness of remedy","paras":[[0,"(a) The authority of any federal agency to sue and be sued in its own name shall not be construed to authorize suits against such federal agency on claims which are cognizable under section 1346(b) of this title, and the remedies provided by this title in such cases shall be exclusive."],[0,"(b)(1) The remedy against the United States provided by sections 1346(b) and 2672 of this title for injury or loss of property, or personal injury or death arising or resulting from the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment is exclusive of any other civil action or proceeding for money damages by reason of the same subject matter against the employee whose act or omission gave rise to the claim or against the estate of such employee. Any other civil action or proceeding for money damages arising out of or relating to the same subject matter against the employee or the employee's estate is precluded without regard to when the act or omission occurred."],[0,"(2) Paragraph (1) does not extend or apply to a civil action against an employee of the Government—"],[1,"(A) which is brought for a violation of the Constitution of the United States, or"],[1,"(B) which is brought for a violation of a statute of the United States under which such action against an individual is otherwise authorized."],[0,"(c) The Attorney General shall defend any civil action or proceeding brought in any court against any employee of the Government or his estate for any such damage or injury. The employee against whom such civil action or proceeding is brought shall deliver within such time after date of service or knowledge of service as determined by the Attorney General, all process served upon him or an attested true copy thereof to his immediate superior or to whomever was designated by the head of his department to receive such papers and such person shall promptly furnish copies of the pleadings and process therein to the United States attorney for the district embracing the place wherein the proceeding is brought, to the Attorney General, and to the head of his employing Federal agency."],[0,"(d)(1) Upon certification by the Attorney General that the defendant employee was acting within the scope of his office or employment at the time of the incident out of which the claim arose, any civil action or proceeding commenced upon such claim in a United States district court shall be deemed an action against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant."],[0,"(2) Upon certification by the Attorney General that the defendant employee was acting within the scope of his office or employment at the time of the incident out of which the claim arose, any civil action or proceeding commenced upon such claim in a State court shall be removed without bond at any time before trial by the Attorney General to the district court of the United States for the district and division embracing the place in which the action or proceeding is pending. Such action or proceeding shall be deemed to be an action or proceeding brought against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant. This certification of the Attorney General shall conclusively establish scope of office or employment for purposes of removal."],[0,"(3) In the event that the Attorney General has refused to certify scope of office or employment under this section, the employee may at any time before trial petition the court to find and certify that the employee was acting within the scope of his office or employment. Upon such certification by the court, such action or proceeding shall be deemed to be an action or proceeding brought against the United States under the provisions of this title and all references thereto, and the United States shall be substituted as the party defendant. A copy of the petition shall be served upon the United States in accordance with the provisions of Rule 4(d)(4) 1 of the Federal Rules of Civil Procedure. In the event the petition is filed in a civil action or proceeding pending in a State court, the action or proceeding may be removed without bond by the Attorney General to the district court of the United States for the district and division embracing the place in which it is pending. If, in considering the petition, the district court determines that the employee was not acting within the scope of his office or employment, the action or proceeding shall be remanded to the State court."],[0,"(4) Upon certification, any action or proceeding subject to paragraph (1), (2), or (3) shall proceed in the same manner as any action against the United States filed pursuant to section 1346(b) of this title and shall be subject to the limitations and exceptions applicable to those actions."],[0,"(5) Whenever an action or proceeding in which the United States is substituted as the party defendant under this subsection is dismissed for failure first to present a claim pursuant to section 2675(a) of this title, such a claim shall be deemed to be timely presented under section 2401(b) of this title if—"],[1,"(A) the claim would have been timely had it been filed on the date the underlying civil action was commenced, and"],[1,"(B) the claim is presented to the appropriate Federal agency within 60 days after dismissal of the civil action."],[0,"(e) The Attorney General may compromise or settle any claim asserted in such civil action or proceeding in the manner provided in section 2677, and with the same effect."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2679?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2679. Exclusiveness of remedy","tname":"Judiciary and Judicial Procedure","by":{"0":"1, 10, 15","1":"12, 23, 6, 23","2":"12"}},{"t":"usc","label":"28 U.S.C. § 2680","url":"https://www.law.cornell.edu/uscode/text/28/2680","subs":["(l)","(a)","(d)"],"stext":{"head":"§2680. Exceptions","paras":[[0,"The provisions of this chapter and section 1346(b) of this title shall not apply to—"],[0,"(a) Any claim based upon an act or omission of an employee of the Government, exercising due care, in the execution of a statute or regulation, whether or not such statute or regulation be valid, or based upon the exercise or performance or the failure to exercise or perform a discretionary function or duty on the part of a federal agency or an employee of the Government, whether or not the discretion involved be abused."],[0,"(b) Any claim arising out of the loss, miscarriage, or negligent transmission of letters or postal matter."],[0,"(c) Any claim arising in respect of the assessment or collection of any tax or customs duty, or the detention of any goods, merchandise, or other property by any officer of customs or excise or any other law enforcement officer, except that the provisions of this chapter and section 1346(b) of this title apply to any claim based on injury or loss of goods, merchandise, or other property, while in the possession of any officer of customs or excise or any other law enforcement officer, if—"],[1,"(1) the property was seized for the purpose of forfeiture under any provision of Federal law providing for the forfeiture of property other than as a sentence imposed upon conviction of a criminal offense;"],[1,"(2) the interest of the claimant was not forfeited;"],[1,"(3) the interest of the claimant was not remitted or mitigated (if the property was subject to forfeiture); and"],[1,"(4) the claimant was not convicted of a crime for which the interest of the claimant in the property was subject to forfeiture under a Federal criminal forfeiture law..1"],[0,"(d) Any claim for which a remedy is provided by chapter 309 or 311 of title 46 relating to claims or suits in admiralty against the United States."],[0,"(e) Any claim arising out of an act or omission of any employee of the Government in administering the provisions of sections 1–31 of Title 50, Appendix.2"],[0,"(f) Any claim for damages caused by the imposition or establishment of a quarantine by the United States."],[0,"[(g) Repealed. Sept. 26, 1950, ch. 1049, §13 (5), 64 Stat. 1043.]"],[0,"(h) Any claim arising out of assault, battery, false imprisonment, false arrest, malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights: Provided, That, with regard to acts or omissions of investigative or law enforcement officers of the United States Government, the provisions of this chapter and section 1346(b) of this title shall apply to any claim arising, on or after the date of the enactment of this proviso, out of assault, battery, false imprisonment, false arrest, abuse of process, or malicious prosecution. For the purpose of this subsection, \"investigative or law enforcement officer\" means any officer of the United States who is empowered by law to execute searches, to seize evidence, or to make arrests for violations of Federal law."],[0,"(i) Any claim for damages caused by the fiscal operations of the Treasury or by the regulation of the monetary system."],[0,"(j) Any claim arising out of the combatant activities of the military or naval forces, or the Coast Guard, during time of war."],[0,"(k) Any claim arising in a foreign country."],[0,"(l) Any claim arising from the activities of the Tennessee Valley Authority."],[0,"(m) Any claim arising from the activities of the Panama Canal Company."],[0,"(n) Any claim arising from the activities of a Federal land bank, a Federal intermediate credit bank, or a bank for cooperatives."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2680?type=usc&year=mostrecent&link-type=html"},"head":"§2680. Exceptions","tname":"Judiciary and Judicial Procedure","by":{"0":"1, 11, 16, 18","1":"5, 6, 42, 5, 24, 33, 6, 13, 28, 6, 15, 20, 28, 37","2":"13, 13, 53"}},{"t":"case","label":"Adams v. Home Owners’ Loan Corp.","cite":"107 F.2d 139","y":1939,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/107/139/","op":1,"sum":"Holding that Home Owners Loan Corporation was not subject to individual tort claim for malicious prosecution under sue-and-be-sued clase, citing Spalding, supra.","sumSrc":"brief:1","by":{"1":"35"}},{"t":"case","label":"Ashwander v. TVA","cite":"297 U.S. 288","y":1936,"id":"1900-1940/297us288","sc":1,"sum":"The Court held that Congress did not abuse its power with the TVA. Justice Hughes argued that the Wilson Dam, the location where the TVA was in the business of generating electricity, had been built originally in the interest of national defense: it produced materials involved in munitions manufacture. The government could sell excess electricity to consumers without violating the Constitution.","sumSrc":"Oyez","by":{"1":"2, 32, 38"}},{"t":"case","label":"Atchley v. TVA","cite":"69 F. Supp. 952","y":1947,"court":"N.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp./69/952/","sum":"Stating that “TVA was exempted from the provisions of the [FTCA] at its own request on the ground that it was already subject to suit and certain of the procedural aspects of the Act would be burdensome.”.","sumSrc":"brief:1","by":{"1":"35, 42"}},{"t":"case","label":"Baldassaro v. United States","cite":"64 F.3d 206","y":1995,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/64/206/","by":{"1":"29"}},{"t":"case","label":"Barr v. Matteo","cite":"360 U.S. 564","y":1959,"id":"1958/350","sc":1,"sum":"Justice John M. Harlan delivered the judgement of the court, reversing the court of appeals. The plurality argued that the statements from the press release were absolutely privileged. Justice Felix Frankfurter, Justice Tom C. Clark, and Justice Charles E. Whittaker joined in the plurality.","sumSrc":"Oyez","by":{"1":"23","2":"4"}},{"t":"case","label":"Bearce v. United States","cite":"614 F.2d 556","y":1980,"url":"https://www.courtlistener.com/c/F.2d/614/556/","by":{"1":"29, 30"}},{"t":"case","label":"Bobo v. TVA","cite":"855 F.3d 1294","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/855/1294/","by":{"1":"17"}},{"t":"case","label":"Canadian Transp. Co. v. United States","cite":"663 F.2d 1081","y":1980,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/663/1081/","by":{"1":"29, 30"}},{"t":"case","label":"Coates v. United States","cite":"181 F.2d 816","y":1950,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/181/816/","by":{"1":"21, 26"}},{"t":"case","label":"Dalehite v. United States","cite":"346 U.S. 15","y":1953,"id":"scdb/1952-101","sc":1,"ar":1,"sum":"As a matter of law, the facts found by the District Court cannot give it jurisdiction of the cause under the Act, because the claim is \"based upon the exercise or performance or the failure to exercise or perform a discretionary function or duty on the plirt of a federal agency or an employee of the Government,\" within the meaning of 28 U. S. C. § 2680 (a), which makes the Act inapplicable to such claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"passim","2":"14, 15, 16"}},{"t":"case","label":"Drake Towing Co. v. Meisner Marine Constr. Co.","cite":"765 F.2d 1060","y":1985,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/765/1060/","by":{"1":"29"}},{"t":"case","label":"Department of Transp. v. Association of Am. R.Rs.","cite":"135 S. Ct. 1225","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1225/","sc":1,"sum":"Holding that Amtrak, a federally owned corporation that is engaged in activities with commercial analogues, is a governmental entity for purposes of separation of powers.","sumSrc":"brief:1","by":{"1":"33"}},{"t":"case","label":"Doe v. McMillan","cite":"412 U.S. 306","y":1973,"id":"1972/71-6356","sc":1,"sum":"Petitioners, parents of District of Columbia (D.bC.) school children, buught this action seeking damages and declaratory and injunctive relief for invasion of privacy'that they claimed resulted from ths dissemination of a congressional report on the D. C. school system that included identification of students in derogatory contexts. The named defendants included members of a House committee, Committee employees; a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Earles v. United States","cite":"935 F.2d 1028","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/935/1028/","by":{"1":"29"}},{"t":"case","label":"Federal Land Bank v. Board of Cnty. Comm’rs","cite":"368 U.S. 146","y":1961,"id":"1961/25","sc":1,"sum":"There is no basis for concluding that Congress did not intend the immunity to apply in this case; and the state personal property tax on petitioner's oil and gas lease and the royalties derived therefrom are unconstitutional by virtue of the Supremacy Clause of the Constitution.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"Feres v. United States","cite":"340 U.S. 135","y":1950,"id":"scdb/1950-013","sc":1,"by":{"1":"27"}},{"t":"case","label":"Gercey v. United States","cite":"540 F.2d 536","y":1976,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/540/536/","by":{"1":"28, 29, 30"}},{"t":"case","label":"Grant v. TVA","cite":"49 F. Supp. 564","y":1942,"court":"E.D. Tenn.","url":"https://www.courtlistener.com/c/F.%20Supp./49/564/","by":{"1":"34, 35"}},{"t":"case","label":"Graves v. United States","cite":"872 F.2d 133","y":1989,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/872/133/","by":{"1":"29"}},{"t":"case","label":"Gray v. Bell","cite":"712 F.2d 490","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/712/490/","by":{"1":"26"}},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"sum":"The Court held that government officials are entitled to qualified immunity but not absolute immunity. Absolute immunity is only available for specific functions that require a total shield from liability.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Lehman v. Nakshian","cite":"453 U.S. 156","y":1981,"id":"1980/80-242","sc":1,"sum":"Respondent was not entitled to a jury trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27, 28"}},{"t":"case","label":"Library of Congress v. Shaw","cite":"478 U.S. 310","y":1986,"id":"1985/85-54","sc":1,"sum":"The no-interest rule applies here so as to preclude the award of increased compensation to respondent's counsel for the delay in receiving payment for his services.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"McMellon v. United States","cite":"387 F.3d 329","y":2004,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/387/329/","by":{"1":"29, 34, 36, 44"}},{"t":"case","label":"People of Porto Rico v. Rosaly y Castillo","cite":"227 U.S. 270","y":1913,"id":"scdb/1912-091","sc":1,"sum":"The government of Porto Rico cannot be sued without its consent.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"17, 18, 42","2":"17, 18, 19"}},{"t":"case","label":"Sea-Land Serv., Inc. v. United States","cite":"919 F.2d 888","y":1990,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/919/888/","by":{"1":"26, 28, 29"}},{"t":"case","label":"Spalding v. Vilas","cite":"161 U.S. 483","y":1896,"id":"scdb/1895-154","sc":1,"sum":"It was the duty of the Postmaster General to cause all cheques or warrants issued under the authority of the act of March 3, 1883, c. 119, 22 Stat. 487, and of the act of August 4, 1886, c. 903, § 8, 24 Stat. 256, 307, 308, to be sent directly to the claimants, and it was his right to call their attention to the provisions of the act of 1883; and if the legislation to which attention was thus invited worked injury …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"TVA v. Hill","cite":"437 U.S. 153","y":1978,"id":"1977/76-1701","sc":1,"op":2,"sum":"The Supreme Court held that Congress’ continued appropriation of funds did not imply that the Dam project was exempt from the ESA. The operation of the Tellico Dam would wipe out the Snail Darter's habitat, so an injunction was the proper remedy.","sumSrc":"Oyez","by":{"1":"2, 32"}},{"t":"case","label":"Tew v. United States","cite":"86 F.3d 1003","y":1996,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/86/1003/","by":{"1":"29"}},{"t":"case","label":"United States v. Gaubert","cite":"499 U.S. 315","y":1991,"id":"1990/89-1793","sc":1,"op":1,"sum":"Describing the discretionary function exception’s scope.","sumSrc":"opinion","by":{"1":"8, 9, 10"}},{"t":"case","label":"United States v. S.A. Empresa de Viacao Aerea Rio Grandense (Varig Airlines)","cite":"467 U.S. 797","y":1984,"id":"1983/82-1349","sc":1,"sum":"Government liability under the FTCA is limited by the discretionary function exception of 28 U.S.C. Section 2680(a), which provides that the federal government may not be held liable for \"[a]ny claim based upon an act or omission of an employee of the Government . . . based upon the exercise or performance or the failure to exercise or perform a discretionary function . . . whether or not the discretion involved be abused.\" The FAA's decision to institute the \"spot-check\" program to monitor compliance with its minimum safety standards was clearly discretionary and protected by Section 2680(a).","sumSrc":"Oyez","by":{"1":"passim","2":"14, 15, 16, 17"}},{"t":"case","label":"United States Aviation Underwriters, Inc. v. United States","cite":"562 F.3d 1297","y":2009,"url":"https://www.courtlistener.com/c/F.3d/562/1297/","by":{"1":"8"}},{"t":"case","label":"United States ex rel. TVA v. An Easement & Right-of-Way Over Two Tracts Of Land","cite":"246 F. Supp. 263","y":1965,"court":"W.D. Ky.","url":"https://www.courtlistener.com/c/F.%20Supp./246/263/","by":{"1":"37"}},{"t":"case","label":"United States ex rel. Welch v. TVA","cite":"327 U.S. 546","y":1946,"id":"scdb/1945-073","sc":1,"sum":"Tennessee Valley Authority built a power 'dam creating a large reservoir, thus flooding a highway which afforded the only reasonable means of access to a large area of mountainous land constituting part of the watershed and lying between the reservoir and a national park. A new road could have been built at a cost disproportionate to its value to the public. After lengthy consideration of all public and private …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3, 32, 33"}},{"t":"case","label":"Westfall v. Erwin","cite":"484 U.S. 292","y":1988,"id":"1987/86-714","sc":1,"sum":"Conduct by federal officials must be discretionary in nature, as well as being within the scope of their employment, before the conduct is absolutely immune from state-law tort liability. See Doe v. McMillan, 412 U. S. 306. Granting absolute immunity for nondiscretionary functions would not further the official immunity doctrine's central purpose of promoting effective government by insulating the decisionmaking …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22, 23","2":"4"}},{"t":"case","label":"Wiggins v. United States","cite":"799 F.2d 962","y":1986,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/799/962/","by":{"1":"28, 29, 30, 37"}},{"t":"law","label":"Pub. L. No. 94-574","url":"https://www.govinfo.gov/link/statute/90/2721","by":{"1":"24"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"1":"24"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","by":{"1":"24"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","by":{"1":"27"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","by":{"1":"27"}},{"t":"usc","label":"28 U.S.C. § 2672","url":"https://www.law.cornell.edu/uscode/text/28/2672","stext":{"head":"§2672. Administrative adjustment of claims","paras":[[0,"The head of each Federal agency or his designee, in accordance with regulations prescribed by the Attorney General, may consider, ascertain, adjust, determine, compromise, and settle any claim for money damages against the United States for injury or loss of property or personal injury or death caused by the negligent or wrongful act or omission of any employee of the agency while acting within the scope of his office or employment, under circumstances where the United States, if a private person, would be liable to the claimant in accordance with the law of the place where the act or omission occurred: Provided, That any award, compromise, or settlement in excess of $25,000 shall be effected only with the prior written approval of the Attorney General or his designee. Notwithstanding the proviso contained in the preceding sentence, any award, compromise, or settlement may be effected without the prior written approval of the Attorney General or his or her designee, to the extent that the Attorney General delegates to the head of the agency the authority to make such award, compromise, or settlement. Such delegations may not exceed the authority delegated by the Attorney General to the United States attorneys to settle claims for money damages against the United States. Each Federal agency may use arbitration, or other alternative means of dispute resolution under the provisions of subchapter IV of chapter 5 of title 5, to settle any tort claim against the United States, to the extent of the agency's authority to award, compromise, or settle such claim without the prior written approval of the Attorney General or his or her designee."],[0,"Subject to the provisions of this title relating to civil actions on tort claims against the United States, any such award, compromise, settlement, or determination shall be final and conclusive on all officers of the Government, except when procured by means of fraud."],[0,"Any award, compromise, or settlement in an amount of $2,500 or less made pursuant to this section shall be paid by the head of the Federal agency concerned out of appropriations available to that agency. Payment of any award, compromise, or settlement in an amount in excess of $2,500 made pursuant to this section or made by the Attorney General in any amount pursuant to section 2677 of this title shall be paid in a manner similar to judgments and compromises in like causes and appropriations or funds available for the payment of such judgments and compromises are hereby made available for the payment of awards, compromises, or settlements under this chapter."],[0,"The acceptance by the claimant of any such award, compromise, or settlement shall be final and conclusive on the claimant, and shall constitute a complete release of any claim against the United States and against the employee of the government whose act or omission gave rise to the claim, by reason of the same subject matter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2672?type=usc&year=mostrecent&link-type=html"},"head":"§2672. Administrative adjustment of claims","tname":"Judiciary and Judicial Procedure","by":{"1":"42","2":"13"}},{"t":"usc","label":"28 U.S.C. § 2674","url":"https://www.law.cornell.edu/uscode/text/28/2674","stext":{"head":"§2674. Liability of United States","paras":[[0,"The United States shall be liable, respecting the provisions of this title relating to tort claims, in the same manner and to the same extent as a private individual under like circumstances, but shall not be liable for interest prior to judgment or for punitive damages."],[0,"If, however, in any case wherein death was caused, the law of the place where the act or omission complained of occurred provides, or has been construed to provide, for damages only punitive in nature, the United States shall be liable for actual or compensatory damages, measured by the pecuniary injuries resulting from such death to the persons respectively, for whose benefit the action was brought, in lieu thereof."],[0,"With respect to any claim under this chapter, the United States shall be entitled to assert any defense based upon judicial or legislative immunity which otherwise would have been available to the employee of the United States whose act or omission gave rise to the claim, as well as any other defenses to which the United States is entitled."],[0,"With respect to any claim to which this section applies, the Tennessee Valley Authority shall be entitled to assert any defense which otherwise would have been available to the employee based upon judicial or legislative immunity, which otherwise would have been available to the employee of the Tennessee Valley Authority whose act or omission gave rise to the claim as well as any other defenses to which the Tennessee Valley Authority is entitled under this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2674?type=usc&year=mostrecent&link-type=html"},"head":"§2674. Liability of United States","tname":"Judiciary and Judicial Procedure","by":{"1":"42","2":"13"}},{"t":"usc","label":"46 U.S.C. § 30901","url":"https://www.law.cornell.edu/uscode/text/46/30901","by":{"1":"13"}},{"t":"usc","label":"46 U.S.C. § 30903","url":"https://www.law.cornell.edu/uscode/text/46/30903","subs":["(a)"],"by":{"1":"33, 29, 31"}},{"t":"usc","label":"46 U.S.C. § 30904","url":"https://www.law.cornell.edu/uscode/text/46/30904","by":{"1":"31"}},{"t":"usc","label":"16 U.S.C. § 831","url":"https://www.law.cornell.edu/uscode/text/16/831","by":{"1":"2, 3, 32, 33"}},{"t":"usc","label":"16 U.S.C. § 831a","url":"https://www.law.cornell.edu/uscode/text/16/831a","subs":["(a)(1)"],"by":{"1":"5, 32"}},{"t":"usc","label":"16 U.S.C. § 831c-2","url":"https://www.law.cornell.edu/uscode/text/16/831c-2","by":{"1":"23"}},{"t":"usc","label":"16 U.S.C. § 831c-3","url":"https://www.law.cornell.edu/uscode/text/16/831c-3","subs":["(a)","(b)","(c)","(h)"],"by":{"1":"5, 32, 5, 32, 5, 5"}},{"t":"usc","label":"16 U.S.C. § 831d","url":"https://www.law.cornell.edu/uscode/text/16/831d","subs":["(l)"],"by":{"1":"37"}},{"t":"usc","label":"16 U.S.C. § 831h-1","url":"https://www.law.cornell.edu/uscode/text/16/831h-1","by":{"1":"4, 32, 34"}},{"t":"usc","label":"16 U.S.C. § 831j","url":"https://www.law.cornell.edu/uscode/text/16/831j","by":{"1":"3, 37"}},{"t":"usc","label":"16 U.S.C. § 831n-4","url":"https://www.law.cornell.edu/uscode/text/16/831n-4","subs":["(h)"],"by":{"1":"3, 37, 3, 4"}},{"t":"usc","label":"16 U.S.C. § 831dd","url":"https://www.law.cornell.edu/uscode/text/16/831dd","by":{"1":"3"}},{"t":"usc","label":"16 U.S.C. § 825s","url":"https://www.law.cornell.edu/uscode/text/16/825s","by":{"1":"38"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","subs":["(b)"],"stext":{"head":"§2401. Time for commencing action against United States","paras":[[0,"(a) Except as provided by chapter 71 of title 41, every civil action commenced against the United States shall be barred unless the complaint is filed within six years after the right of action first accrues. The action of any person under legal disability or beyond the seas at the time the claim accrues may be commenced within three years after the disability ceases."],[0,"(b) A tort claim against the United States shall be forever barred unless it is presented in writing to the appropriate Federal agency within two years after such claim accrues or unless action is begun within six months after the date of mailing, by certified or registered mail, of notice of final denial of the claim by the agency to which it was presented."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2401?type=usc&year=mostrecent&link-type=html"},"head":"§2401. Time for commencing action against United States","tname":"Judiciary and Judicial Procedure","by":{"1":"42","2":"13, 53"}},{"t":"usc","label":"31 U.S.C. § 1116","url":"https://www.law.cornell.edu/uscode/text/31/1116","by":{"1":"3"}},{"t":"case","label":"Cary v. Curtis","cite":"44 U.S. 236","y":1845,"id":"scdb/1845-022","sc":1,"by":{"2":"11"}},{"t":"case","label":"Dean v. Herrington","cite":"668 F. Supp. 646","y":1987,"court":"E.D. Tenn.","url":"https://www.courtlistener.com/c/F.%20Supp./668/646/","by":{"2":"19"}},{"t":"case","label":"Keifer & Keifer v. Reconstruction Fin. Corp.","cite":"306 U.S. 381","y":1939,"id":"scdb/1938-149","sc":1,"sum":"1. A Regional Agricultural Credit Corporation, chartered by the Reconstruction Finance Corporation by authority of § 201 (e) of the Emergency Relief and Construction Act of 1932, and which under that statute is government-financed and managed and empowered to make loans to farmers and stockmen for agricultural purposes or for raising and marketing livestock-held subject to suit. Pp. 392, et seq. Neither the statute …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26, 27"}},{"t":"case","label":"Nat’l Cable & Telecomms. Ass’n v. Brand X Internet Servs.","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"Steel Co. v. Citizens for Better Environment","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"TVA v. EPA","cite":"278 F.3d 1184","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/278/1184/","by":{"2":"20"}},{"t":"case","label":"TVA v. United States","cite":"13 Cl. Ct. 692","y":1987,"url":"https://www.courtlistener.com/c/Cl.%20Ct./13/692/","by":{"2":"19"}}]};